        if !combiners[node_id].queued_ops().contains(rid) {
            if combiner_request_id_fresh(combiners.remove(node_id), rid) {
                assert forall|n|
                    (#[trigger] combiners.contains_key(
                        n,
                    )) implies !combiners[n].queued_ops().contains(rid) by {
                    if n != node_id {
