> {
    Map::new(
        local_reads.dom(),
        |rid|
            match local_reads.index(rid) {
                ReadonlyState::Init { op } => SReadReq::Init { op },
                ReadonlyState::VersionUpperBound { version_upper_bound: idx, op } => SReadReq::Req {
